import{_ as t,o,c as a,a2 as n}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Create and access a workspace","description":"Sign in, choose or create a workspace, understand roles at a high level, and the limits of guest preview.","frontmatter":{"title":"Create and access a workspace","description":"Sign in, choose or create a workspace, understand roles at a high level, and the limits of guest preview.","audience":"user","status":"current","last_verified":"2026-07-19T00:00:00.000Z"},"headers":[],"relativePath":"get-started/create-and-access-a-workspace.md","filePath":"get-started/create-and-access-a-workspace.md","lastUpdated":null}'),r={name:"get-started/create-and-access-a-workspace.md"};function s(i,e,c,l,d,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="create-and-access-a-workspace" tabindex="-1">Create and access a workspace</h1><p>A <strong>workspace</strong> is your private Zenin environment: your connected accounts, watchlists, portfolio, journal entries, and saved views. You sign in once, then work inside a workspace.</p><h2 id="sign-in" tabindex="-1">Sign in</h2><ol><li>Open the Zenin app.</li><li>Sign in with your account email and password.</li><li>If your organization uses single sign-on or multi-factor authentication, complete that step when prompted.</li></ol><blockquote><p>Multi-factor authentication and SSO availability depend on the deployed provider configuration. If a method is not offered, it is not enabled for your workspace.</p></blockquote><h2 id="choose-or-create-a-workspace" tabindex="-1">Choose or create a workspace</h2><p>After sign in you land in a workspace. You can:</p><ul><li><strong>Open an existing workspace</strong> you already belong to.</li><li><strong>Create a new workspace</strong> to start fresh with your own connections and data.</li><li><strong>Switch workspaces</strong> from the workspace switcher when you belong to more than one.</li></ul><p>Each workspace keeps its own portfolio, watchlists, and journal — switching workspaces does not merge their data.</p><h2 id="roles-at-a-high-level" tabindex="-1">Roles at a high level</h2><p>Workspaces use member roles to control who can change settings and connections:</p><ul><li><strong>Owner</strong> — full control, including billing, member management, and connected-account configuration.</li><li><strong>Member</strong> — uses the workspace, connects read-only data sources they are permitted to add, and contributes journal/research content.</li><li><strong>Guest / preview</strong> — can explore a read-only preview of the workspace without representing local preview actions as live brokerage execution.</li></ul><p>Exact permission boundaries depend on your plan and the workspace configuration. When in doubt, ask the workspace owner.</p><h2 id="guest-preview-limitations" tabindex="-1">Guest preview limitations</h2><p>Guest mode is an <strong>explicit preview entry point</strong>. It lets you look around without connecting anything, but:</p><ul><li>Preview actions are <strong>not</strong> live brokerage executions.</li><li>Connected-account data shown in preview is read-only context, not your own imported positions unless you sign in.</li><li>Some actions that require saving (journal entries, saved views) are unavailable or limited until you sign in to a workspace.</li></ul><p><strong>Next:</strong> <a href="/get-started/connect-data-sources">Connect data sources</a></p>',17)])])}const h=t(r,[["render",s]]);export{g as __pageData,h as default};
